solution.solution.cpp:
#include <algorithm>
#include <map>
#include <sstream>
#include <string>

struct Settings
{
    int music{ 70 }, effects{ 85 };
    bool fullscreen{ false };
    bool shake{ true };
    int jumpKey{ 32 };
};

namespace
{
    std::string trim(const std::string& s)
    {
        const auto b{ s.find_first_not_of(" \t") };
        if (b == std::string::npos) return "";
        const auto e{ s.find_last_not_of(" \t") };
        return s.substr(b, e - b + 1);
    }

    bool toInt(const std::string& s, int& out)
    {
        if (s.empty()) return false;
        std::size_t used{ 0 };
        try { out = std::stoi(s, &used); } catch (...) { return false; }
        return used == s.size();
    }
}

Settings parseSettings(const std::string& text)
{
    std::map<std::string, std::string> values;
    std::istringstream in{ text };
    for (std::string line; std::getline(in, line);)
    {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        const auto eq{ line.find('=') };
        if (eq == std::string::npos) continue;
        values[trim(line.substr(0, eq))] = trim(line.substr(eq + 1));
    }

    Settings s;
    int version{ 2 };
    if (values.count("version") && (!toInt(values["version"], version) || version < 1 || version > 2)) return s;
    const int volumeScale{ version == 1 ? 10 : 1 };

    int v{ 0 };
    if (values.count("music") && toInt(values["music"], v)) s.music = std::clamp(v * volumeScale, 0, 100);
    if (values.count("effects") && toInt(values["effects"], v)) s.effects = std::clamp(v * volumeScale, 0, 100);
    if (values.count("fullscreen") && toInt(values["fullscreen"], v) && (v == 0 || v == 1)) s.fullscreen = v == 1;
    if (values.count("shake") && toInt(values["shake"], v) && (v == 0 || v == 1)) s.shake = v == 1;
    if (values.count("key.jump") && toInt(values["key.jump"], v) && v >= 1 && v <= 512) s.jumpKey = v;
    return s;
}

std::string writeSettings(const Settings& s)
{
    return "version=2\nmusic=" + std::to_string(s.music) + "\neffects=" + std::to_string(s.effects) +
           "\nfullscreen=" + (s.fullscreen ? "1" : "0") + "\nshake=" + (s.shake ? "1" : "0") +
           "\nkey.jump=" + std::to_string(s.jumpKey) + "\n";
}

unitTests:
TEST("defaults for an empty file") { const Settings s = parseSettings(""); CHECK_EQ(s.music, 70); CHECK_EQ(s.effects, 85); CHECK(!s.fullscreen); CHECK(s.shake); CHECK_EQ(s.jumpKey, 32); }
TEST("reading values") {
    const Settings s = parseSettings("version=2
 music = 40 
effects=150
fullscreen=1
shake=0
key.jump=87
");
    CHECK_EQ(s.music, 40); CHECK_EQ(s.effects, 100); CHECK(s.fullscreen); CHECK(!s.shake); CHECK_EQ(s.jumpKey, 87);
}
TEST("bad values keep their defaults") {
    const Settings s = parseSettings("music=7x
fullscreen=2
key.jump=0
shake
volume=3
effects=-5
");
    CHECK_EQ(s.music, 70); CHECK(!s.fullscreen); CHECK_EQ(s.jumpKey, 32); CHECK(s.shake); CHECK_EQ(s.effects, 0);
}
TEST("old and future versions") {
    const Settings old = parseSettings("version=1
music=4
effects=12
"); CHECK_EQ(old.music, 40); CHECK_EQ(old.effects, 100);
    const Settings future = parseSettings("version=3
music=10
"); CHECK_EQ(future.music, 70);
}
TEST("writing and reading back") {
    Settings s; s.music = 55; s.fullscreen = true; s.jumpKey = 265;
    const std::string text = writeSettings(s);
    CHECK_EQ(text, std::string("version=2
music=55
effects=85
fullscreen=1
shake=1
key.jump=265
"));
    const Settings back = parseSettings(text); CHECK_EQ(back.music, 55); CHECK(back.fullscreen); CHECK_EQ(back.jumpKey, 265);
}

